import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function requiredText(value: unknown, label: string): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 입력해 주세요.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr02110Controller {
  @Post('/retirement-criterias')
  @HttpCode(200)
  async createRetirementCriteria(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const criteriaName = requiredText(data['criteriaName'], '기준명');
    const calculationBasis = requiredText(data['calculationBasis'], '퇴직금 산정 기준');
    const startDate = requiredText(data['startDate'], '적용 시작일');
    if (criteriaName.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '기준명은 200자 이하로 입력해 주세요.');
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작일은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO retirement_criteria (criteria_name, calculation_basis, start_date, created_at, updated_at)
         VALUES (:criteriaName, :calculationBasis, CAST(:startDate AS date), now(), now())
         RETURNING retirement_criteria_id AS "retirementCriteriaId"`,
        { criteriaName, calculationBasis, startDate },
      );
      return rows[0];
    });
  }

  @Get('/retirement-criterias')
  async listRetirementCriterias(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, MAX_SIZE);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT retirement_criteria_id AS "retirementCriteriaId",
                criteria_name AS "criteriaName",
                calculation_basis AS "calculationBasis",
                start_date AS "startDate"
           FROM retirement_criteria
          ORDER BY start_date DESC, retirement_criteria_id DESC
          LIMIT :size OFFSET :offset`,
        { size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM retirement_criteria`,
        {},
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

