import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  DateInput,
  Tiles,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr02110Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [criteriaName, setCriteriaName] = useState('');
  const [calculationBasis, setCalculationBasis] = useState('');
  const [startDate, setStartDate] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/retirement-criterias', role, undefined, { page, size: SIZE }),
    [page, role],
  );

  function openCreate() {
    setCriteriaName('');
    setCalculationBasis('');
    setStartDate('');
    setCreating(true);
  }

  async function submit() {
    const missing: string[] = [];
    if (!criteriaName.trim()) missing.push('기준명');
    if (!calculationBasis.trim()) missing.push('퇴직금 산정 기준');
    if (!startDate) missing.push('적용 시작일');
    if (missing.length > 0) {
      throw new Error('필수 항목을 입력해 주세요: ' + missing.join(', '));
    }
    await call('POST', '/retirement-criterias', role, { criteriaName, calculationBasis, startDate });
    notify('퇴직기준을 설정했습니다.');
    setCreating(false);
    setPage(0);
    reload();
  }

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>퇴직기준</h2>
        <Tiles items={[['설정된 기준', <Num value={total} />]]} />
      </section>
      <section className="box span-12">
        <h2>기준 목록</h2>
        <Band total={total}>
          <button type="button" onClick={openCreate}>퇴직기준 설정</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            { key: 'criteriaName', label: '기준명' },
            { key: 'calculationBasis', label: '퇴직금 산정 기준' },
            { key: 'startDate', label: '적용 시작일', render: (r) => <DateText value={r.startDate} /> },
          ]}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty="설정된 퇴직기준이 없습니다."
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="퇴직기준 설정" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="기준명" required>
              <TextInput value={criteriaName} onChange={setCriteriaName} />
            </Field>
            <Field label="퇴직금 산정 기준" required wide>
              <TextInput value={calculationBasis} onChange={setCalculationBasis} multiline />
            </Field>
            <Field label="적용 시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {detail ? (
        <Drawer title="퇴직기준 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['기준명', String(detail.criteriaName ?? '')],
              ['퇴직금 산정 기준', String(detail.calculationBasis ?? '')],
              ['적용 시작일', <DateText value={detail.startDate} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
